INSERT INTO "Product" ("id", "name", "slug", "description", "shortDescription", "brandId", "categoryId", "images", "indicativePrice", "originalPrice", "discountPercent", "rating", "reviewCount", "isVerifiedRating", "specifications", "keyFeatures", "isFeatured", "isTrending", "isBestDeal", "isTopPick", "isNewArrival", "availability", "priceLastUpdated", "viewsCount", "clicksCount", "metaTitle", "metaDescription", "createdAt", "updatedAt") VALUES ('cmwo8zrtg0014banpe6uuclw5', 'Apple iPhone 15 (128 GB) - Blue', 'apple-iphone-15-128gb-blue', 'iPhone 15 brings you Dynamic Island, a 48MP Main camera, and USB-C, all in a durable color-infused glass and aluminum design. Powered by the blazing-fast A16 Bionic chip.', 'Dynamic Island, 48MP Camera, USB-C, A16 Bionic Chip', 'cmwo8zriq0007banphcigsbrm', 'cmwo8zrnx000lbanph1doq3zo', '["https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?w=800&auto=format&fit=crop&q=80"]', 69999, 79900, 12, 4.6, 3420, TRUE, '{"Display":"6.1-inch Super Retina XDR OLED","Processor":"A16 Bionic chip with 5-core GPU","Camera":"48MP Main + 12MP Ultra Wide with 2x Telephoto","Front Camera":"12MP TrueDepth","Connector":"USB-C","Battery":"All-day battery life (Up to 20 hrs video)","Water Resistance":"IP68 (6 meters up to 30 mins)"}', '["Dynamic Island bubbles up alerts and Live Activities","Innovative 48MP Main camera with 2x optical-quality Telephoto","Durable color-infused glass with textured matte finish","Superfast A16 Bionic chip with next-gen computational photography","Universal USB-C charging connector"]', TRUE, TRUE, FALSE, TRUE, FALSE, 'IN_STOCK', '2026-11-20T00:35:39.028Z', 0, 0, NULL, NULL, '2026-11-20T00:35:39.028Z', '2026-11-20T00:35:39.028Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "description", "shortDescription", "brandId", "categoryId", "images", "indicativePrice", "originalPrice", "discountPercent", "rating", "reviewCount", "isVerifiedRating", "specifications", "keyFeatures", "isFeatured", "isTrending", "isBestDeal", "isTopPick", "isNewArrival", "availability", "priceLastUpdated", "viewsCount", "clicksCount", "metaTitle", "metaDescription", "createdAt", "updatedAt") VALUES ('cmwo8zruo001cbanppm24btrj', 'Samsung Galaxy S24 5G (8GB RAM, 256GB Storage) - Cobalt Violet', 'samsung-galaxy-s24-5g-256gb', 'Galaxy AI is here. Search like never before with Circle to Search, get real-time voice translation on a call, and format notes into a clear summary. Featuring Armor Aluminum 2.0 and 50MP AI Camera.', 'Galaxy AI, 50MP Camera, Dynamic AMOLED 2X, Snapdragon 8 Gen 3', 'cmwo8zrj10008banpuvw7vuxj', 'cmwo8zrnx000lbanph1doq3zo', '["https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1580910051074-3eb694886505?w=800&auto=format&fit=crop&q=80"]', 64999, 79999, 19, 4.5, 1890, TRUE, '{"Display":"6.2-inch FHD+ Dynamic AMOLED 2X (120Hz)","Processor":"Exynos 2400 / Snapdragon 8 Gen 3","RAM & Storage":"8GB RAM, 256GB UFS 4.0","Camera":"50MP Wide + 12MP Ultra-Wide + 10MP Telephoto (3x)","Battery":"4000 mAh with 25W Fast Charging","AI Features":"Circle to Search, Live Translate, Note Assist"}', '["Galaxy AI transforms mobile convenience","Stunning 2600 nits peak outdoor brightness","ProVisual Engine for ultra-clear night photography","7 Generations of OS Upgrades & 7 Years of Security Updates"]', TRUE, FALSE, TRUE, FALSE, FALSE, 'IN_STOCK', '2026-11-20T00:35:39.072Z', 1, 0, NULL, NULL, '2026-11-20T00:35:39.072Z', '2026-11-20T00:52:13.466Z') ON CONFLICT ("id") DO NOTHING;
